// One page of a project's calls as of a snapshot. The sort key is one number, negated for
// descending order, so unknowns sort last and ties break by id in both orders; the cursor is the
// last row's (unknown, key, id).
func (q *Queries) ListCalls(ctx context.Context, arg ListCallsParams) ([]ListCallsRow, error) {
	rows, err := q.db.Query(ctx, listCalls,
		arg.AfterCursor,
		arg.CursorUnknown,
		arg.CursorValue,
		arg.CursorID,
		arg.MaxRows,
		arg.SortBy,
		arg.Descending,
		arg.OrganisationID,
		arg.ProjectID,
		arg.SnapshotAt,
		arg.FromAt,
		arg.ToAt,
		arg.Room,
		arg.Channels,
		arg.AnswerMin,
		arg.AnswerMax,
		arg.DurationMin,
		arg.DurationMax,
		arg.TurnsMin,
		arg.TurnsMax,
		arg.UnknownAnswer,
		arg.UnknownDuration,
		arg.UnknownTurns,
		arg.MatchNone,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListCallsRow
	for rows.Next() {
		var i ListCallsRow
		if err := rows.Scan(
			&i.ID,
			&i.RoomName,
			&i.RoomSid,
			&i.StartAt,
			&i.StartedAt,
			&i.EndedAt,
			&i.EndState,
			&i.DurationSeconds,
			&i.Participants,
			&i.Channel,
			&i.TurnCount,
			&i.AnswerMs,
			&i.AnswerMsMedian,
			&i.Models,
			&i.Pipeline,
			&i.AgentKey,
			&i.KeyUnknown,
			&i.SortValue,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

